const $=id=>document.getElementById(id), MODELS=window.GPRO_DEEP_MODELS||[],KEY='gpro-income-wizard-v1',THEME='gpro-theme-preference',money=n=>Math.round(n).toLocaleString('ru-RU')+' ₽';
