try{const old=JSON.parse(localStorage.getItem(KEY)||'null');if(old&&typeof old==='object'&&!Array.isArray(old)&&Number.isInteger(old.step)){state={...state,...old,step:Math.min(6,Math.max(1,old.step)),inputs:old.inputs||{},finance:old.finance||{},done:old.done||{}};}}catch{}
const controls=['target','hours','budget','city','interest','workFormat'];const headings=[['Твои возможности','Сейчас укажем ресурсы. Далее покажем все подходящие идеи и объясним, почему они могут подойти.'],['Выбираем дело','Начни с рекомендаций или раскрой все варианты. Далее разберём выбранное дело простыми словами.'],['Разбираем бизнес','Здесь выясняем, что продаём, кому, какой нужен комплект и где искать клиента. Далее проверим предварительную экономику.'],['Проверяем экономику','Пока используем редактируемые гипотезы, не рыночную статистику. Далее выясним, как получить первые заказы и проверить эти цифры на практике.'],['Маршрут запуска','Следуй по дням и этапам: подготовка, объявление, первые клиенты и контроль прибыли. Далее соберём результаты в бизнес-план.'],['Твой бизнес-план','Сводим решения, экономику, инструкции и дальнейшие действия. Скачай читаемый HTML-файл, чтобы работать с планом вне сайта.']];
