function theme(v){const light=v==='light';document.documentElement.dataset.theme=light?'light':'dark';$('theme').textContent=light?'☀ Светлая':'☾ Тёмная';$('theme').setAttribute('aria-pressed',String(light));$('theme').setAttribute('aria-label',light?'Включить тёмную тему':'Включить светлую тему');}try{theme(localStorage.getItem(THEME)==='light'?'light':'dark');}catch{theme('dark');}
$('theme').onclick=()=>{const v=document.documentElement.dataset.theme==='light'?'dark':'light';theme(v);try{localStorage.setItem(THEME,v);}catch{}};
for(const id of controls)if(state.inputs[id]!==undefined)$(id).value=state.inputs[id];
function readInputs(){return Object.fromEntries(controls.map(k=>[k,$(k).value]));}
function validInputs(){const i=readInputs();return Number.isFinite(+i.target)&&+i.target>=1000&&+i.target<=10000000&&+i.hours>0&&+i.budget>=0;}
const selected=()=>MODELS.find(m=>m.id===state.selected)||null;const playbook=()=>selected()?.category==='events'&&selected()?.title==='Организация настольных и финансовых игр'?window.GPRO_PLAYBOOKS?.games:null;const chosenFormat=()=>playbook()?.formats[state.formatIndex||0]||null;const cleaning=()=>selected()?.title==='Клининг квартир'?window.GPRO_CLEANING_DETAIL:null;const brief=()=>window.GPRO_MODEL_BRIEFS?.find(x=>x.id===state.selected)||null;const operation=()=>window.GPRO_MODEL_OPERATIONS?.find(x=>x.id===state.selected)||null;const specialist=()=>window.GPRO_SPECIALIST_GUIDES?.[selected()?.category]||null;const capitalGuide=()=>window.GPRO_CAPITAL_GUIDES?.[state.selected]||null;const expandedGuide=()=>window.GPRO_EXPANDED_GUIDES?.[selected()?.category]||null;const modelPlan=()=>{const m=selected(),b=brief(),g=guide(),city=state.inputs.city||'своём городе';if(!m||!b)return null;const op=operation(),offer=b.product,customer=op?.customer||b.customers,kit=b.equipment,channel=g?.channels||m.channels;const stages=[['День 1 · Выбери конкретный продукт','Сформулируй одну услугу: '+offer+'. Для кого: '+customer+'. '+(op?.validation||b.firstTest),'Определён продукт и понятный результат для клиента'],['День 2 · Изучи спрос и цены','Найди 8–12 предложений в '+city+'. Выпиши стоимость, состав услуги, фотографии и отзывы. Отдельно посчитай стартовые приобретения: '+kit+'.','Таблица конкурентов, прайс и список покупок'],['День 3 · Подготовь предложение','Для этого предложения подготовь: '+kit+'. Затем сделай 4–6 собственных фото товара, процесса или примеров, укажи стоимость, содержание, ограничения и способ заказа. Публикуй только подтверждённое предложение. Каналы: '+channel+'.','Одно опубликованное объявление и понятный прайс'],['Дни 4–7 · Получи обращения','Отвечай на сообщения покупателей: '+customer+'. Подбери 5 смежных партнёров, которым интересен именно продукт «'+offer+'». Отправь персональное предложение с конкретной пользой, запиши источник каждого обращения и причину отказа; без массового спама.','Первые диалоги и данные о спросе'],['Дни 8–10 · Первый платный заказ','Согласуй объём, цену, срок, оплату и ответственность. Для этой модели порядок исполнения: '+(op?.delivery||'выполнение, проверка результата и отзыв')+'. При отсутствии заявок измени фото, предложение или площадку и повтори тест.','Первый заказ или конкретные причины отсутствия продаж'],['Дни 11–15 · Проверка цифр','Для этой модели особенно важно учитывать: '+(op?.costs||m.costs)+'. Для каждого заказа отдельно запиши выручку, затраты, налоги и время. Цена привлечения — рекламные расходы / оплаченные заказы.','Фактическая маржа и рабочие часы'],['Дни 16–30 · Улучшение продукта','Сравни прибыль по разным заказам, убери невыгодные операции, собери отзывы и уточни условия. Не увеличивай вложения по результату одного удачного заказа.','Проверенный основной пакет'],['Дни 31–60 · Развитие потока','Проверь минимум два канала продаж, предложи партнёрам конкретный продукт и условия сотрудничества, измерь стабильность заявок и доход за час.','Один стабильный канал и подтверждённая экономика'],['Дни 61–90 · Решение о росте','Сравни оплаченные заказы, денежный результат, время, сезонность и риски. Только при повторяемой прибыли планируй следующую покупку или сотрудника.','Решение: расширять, корректировать или остановить']];const noun=m.category==='resale'?'товар':(['rental','season'].includes(m.category)||/аренд|прокат/i.test(m.title))?'комплект':m.category==='property'?'помещение или место':'услугу';const ad='Предложение в '+city+': '+offer+'. Подойдёт: '+customer+'. '+(m.category==='resale'?'Покажу реальные фотографии, состояние, комплектацию и известные дефекты.':m.category==='rental'?'Покажу комплект, условия аренды, выдачи и возврата.':m.category==='property'?'Уточню назначение помещения, оснащение, график и полную стоимость.':'Согласуем конкретный объём работ, сроки и цену до начала.')+' Напишите, какая задача, какой '+noun+' вам нужен и на какую дату.';const partner='Здравствуйте! Я развиваю направление «'+offer+'» в '+city+'. Работаю для клиентов: '+customer+'. Подскажите, возникают ли у вас подобные запросы? Могу прислать понятный пакет, стоимость и условия сотрудничества.';return{stages,ad,partner,kit,offer,customer,channel,pricing:b.pricing,operation:op};};const guide=()=>window.GPRO_CATEGORY_GUIDES?.[selected()?.category]||null;
const create=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
const rank=m=>{const p=state.inputs,b=Number(p.budget)||0,t=Number(p.target)||0,available=Math.max(0,Number(p.hours)||0)*4.33;const kind=/вендинг|автомат/i.test(m.title)?'vending':/точка кофе с собой|точка шаурмы/i.test(m.title)?'food':m.category==='resale'?'resale':['deep-5','deep-new-9'].includes(m.id)?'lease':m.id==='deep-6'?'space':(['rental'].includes(m.category)&&m.id!=='deep-29'||/аренда SUP|сдача автомобиля в аренду/i.test(m.title))?'rental':'service';const contribution=m.ticket-m.variable-Math.round(m.ticket*.1)-m.ticket*.06,required=contribution>0?Math.ceil(t/contribution):Infinity;const monthlyHoursPerSale=Math.max(.25,m.hours||1),units=1,util=.4;let indicativeCapacity=Math.floor(available/monthlyHoursPerSale*util);if(kind==='rental')indicativeCapacity=Math.min(indicativeCapacity,Math.floor(30*units*util));if(kind==='lease')indicativeCapacity=Math.floor(units*util);if(kind==='space')indicativeCapacity=Math.floor(26*units*util);if(kind==='resale')indicativeCapacity=Math.min(indicativeCapacity,Math.floor(Math.max(1,b/Math.max(1,m.variable))));if(kind==='vending'||kind==='food')indicativeCapacity=0;const affordable=m.minCapital<=b,shortfall=Math.max(0,m.minCapital-b),mathReachable=Number.isFinite(required)&&indicativeCapacity>=required,needsValidation=kind==='vending'||kind==='food'||kind==='lease'||kind==='space';let score=50+(affordable?25:-70)+(p.interest==='any'||p.interest===m.category?20:0)+(mathReachable?20:needsValidation?0:-25);if(p.workFormat==='online'&&!['digital','creative'].includes(m.category))score-=20;if(p.workFormat==='offline'&&['digital','creative'].includes(m.category))score-=8;const reasons=[affordable?'Минимальный старт вписывается в бюджет':'Не хватает минимум '+money(shortfall)+' до указанного старта',p.interest==='any'||p.interest===m.category?'Соответствует выбранной тематике':'Тематика не совпадает с предпочтением',mathReachable?'Предварительная мощность покрывает расчётный объём':needsValidation?'Для этого формата нет данных о реальной загрузке и постоянных расходах':'При условной загрузке 40% мощность меньше необходимого объёма'];if(contribution<=0)reasons.push('При предварительных затратах вклад продажи не положительный');if(kind==='resale')reasons.push('Нужен оборотный капитал для закупки и учёт неликвидов');if(kind==='lease'||kind==='space')reasons.push('Проверь договор аренды, право субаренды и простой');if(kind==='food'||kind==='vending')reasons.push('Проверь поток покупателей, аренду, персонал и обслуживание');if(kind==='rental')reasons.push('Проверь фактически оплаченные дни, ремонт и простой оборудования');return{m,score,orders:required,likelyHours:required*monthlyHoursPerSale/util,feasible:affordable&&mathReachable&&!needsValidation,needsValidation,kind,indicativeCapacity,reasons,shortfall};};
function rail(){const root=$('stepRail');root.replaceChildren();for(let i=1;i<=6;i++){const b=create('button',String(i)+(i<state.step?' ✓':''),'wizard-dot');b.type='button';b.classList.toggle('active',i===state.step);b.classList.toggle('passed',i<state.step);b.title=headings[i-1][0];b.disabled=i>state.step;b.onclick=()=>{state.step=i;draw();};root.append(b);}}
function qualitativeProfile(m){const op=window.GPRO_MODEL_OPERATIONS?.find(x=>x.id===m.id);const id=m.id,cat=m.category,staff=['deep-1','deep-2','deep-9','deep-new-7','deep-new-8'].includes(id),regulated=['deep-17','deep-27','deep-new-6','deep-new-7','deep-new-8','deep-5','deep-6','deep-new-9'].includes(id),equipment=['rental','season','cleaning','repair','auto'].includes(cat)||['deep-new-6','deep-new-7','deep-new-8'].includes(id),complex=regulated||staff||m.minCapital>=200000,fast=['digital','repair','cleaning','resale'].includes(cat)||id==='deep-29';const specificRisk=op?.costs||m.risks||'Проверка спроса и исполнения';const firstAction=op?.validation||m.validation||'Сделай проверку спроса до вложений';const dependency=op?.delivery||'Проверь порядок выполнения';return{complexity:complex?'Высокая':equipment?'Средняя':'Ниже средней',firstSale:regulated?'Проверить условия: '+firstAction:fast?'Быстрый тест: '+firstAction:'Первые действия: '+firstAction,staff:staff?'Вероятно нужны сотрудники/подрядчики; '+dependency:'Старт возможен без штатного персонала при наличии нужных навыков',equipment:equipment?'Проверить комплект и исправность; '+dependency:'Преимущественно нужны навыки и процессы; '+dependency,risk:specificRisk,reason:'Индивидуальные действия по модели плюс предварительная экспертная классификация. Это не рыночная статистика.'};}
function compareIdeas(root){const ids=Array.isArray(state.compareIds)?state.compareIds.filter(id=>MODELS.some(m=>m.id===id)).slice(0,3):[];if(!ids.length)return;const rows=ids.map(id=>rank(MODELS.find(m=>m.id===id))),wrap=create('section',undefined,'plan-diagnostics');wrap.append(create('h3','Сравнение выбранных направлений'));wrap.append(create('p','Это предварительный отбор, а не финансовые прогнозы. Для полноценной оценки каждой идеи перейди в её экономику и проверь налог, постоянные расходы и реальные продажи.','hint'));const scroll=create('div');scroll.style.overflowX='auto';const table=create('table');table.style.minWidth='640px';const fields=[['Критерий',x=>x.m.title],['Минимальный старт',x=>money(x.m.minCapital)],['Нехватка бюджета',x=>money(x.shortfall)],['Цена одной продажи (гипотеза)',x=>money(x.m.ticket)],['Предварительный вклад с продажи',x=>money(x.m.ticket-x.m.variable-Math.round(x.m.ticket*.1)-x.m.ticket*.06)],['Продаж для цели без постоянных расходов',x=>Number.isFinite(x.orders)?String(x.orders):'Недостижимо'],['Условная мощность при 40% загрузке',x=>x.needsValidation?'Нужна отдельная проверка':String(x.indicativeCapacity)],['Оценка соответствия',x=>x.feasible?'Предварительно подходит':x.needsValidation?'Требует проверки':'Есть ограничения'],['Сложность запуска (оценка)',x=>qualitativeProfile(x.m).complexity],['Когда тестировать первые продажи',x=>qualitativeProfile(x.m).firstSale],['Зависимость от персонала',x=>qualitativeProfile(x.m).staff],['Зависимость от оборудования',x=>qualitativeProfile(x.m).equipment],['Ключевой риск',x=>qualitativeProfile(x.m).risk]];for(const [label,value]of fields){const tr=create('tr');tr.append(create('th',label));for(const x of rows)tr.append(create('td',value(x)));table.append(tr);}scroll.append(table);wrap.append(scroll);const buttons=create('div',undefined,'wizard-actions');const clear=create('button','Очистить сравнение','secondary');clear.type='button';clear.onclick=()=>{state.compareIds=[];save();drawIdeas();};buttons.append(clear);wrap.append(buttons);root.prepend(wrap);}
function drawIdeas(){const ordered=MODELS.map(rank).sort((a,b)=>b.score-a.score);const list=[];const sectors={};for(const item of ordered){if((sectors[item.m.category]||0)>=2)continue;list.push(item);sectors[item.m.category]=(sectors[item.m.category]||0)+1;if(list.length===12)break;}if(list.length<12)for(const item of ordered){if(list.includes(item))continue;list.push(item);if(list.length===12)break;}$('ideasIntro').textContent='Из '+MODELS.length+' направлений хотя бы минимальному бюджету соответствуют '+ordered.filter(x=>x.shortfall===0).length+'. Показываем до 12 разных вариантов по соответствию. Для части моделей цель может требовать больше часов, чем у тебя есть.';const root=$('ideaCards');root.replaceChildren();document.querySelectorAll('.idea-toggle').forEach(n=>n.remove());const showAll=create('button',state.showAllIdeas?'Свернуть до 12 ↑':'Показать все '+ordered.length+' вариантов ↓','secondary');showAll.type='button';showAll.classList.add('idea-toggle');showAll.onclick=()=>{state.showAllIdeas=!state.showAllIdeas;drawIdeas();save();};root.before(showAll);if(!list.length){root.append(create('p','Не удалось рассчитать рекомендации по текущим вводным.','hint'));return;}for(const {m,orders,likelyHours,feasible,needsValidation,kind,indicativeCapacity,reasons,shortfall} of (state.showAllIdeas?ordered:list)){const card=create('article',undefined,'wizard-idea'),h=create('h3',m.title),meta=create('p','Старт от '+money(m.minCapital)+' · ориентир выручки за заказ '+money(m.ticket)+' · '+m.audience,'hint'),tag=create('p',feasible?'Предварительно совместимо с бюджетом и часами — спрос ещё не проверен':needsValidation?'Нужна отдельная оценка спроса, постоянных расходов и мощности':'Цель не подтверждается упрощённым расчётом: проверь экономику','wizard-signal'),detail=create('p','Для цели при предварительной марже требуется '+(Number.isFinite(orders)?orders+' продаж':'положительная маржа')+'. '+(needsValidation?'Для этого формата почасовой расчёт не доказывает достижимость дохода.':'Условная трудоёмкость цели: '+(Number.isFinite(likelyHours)?Math.ceil(likelyHours)+' ч/мес.':'не определена')+'; предварительная мощность '+indicativeCapacity+' операций/мес.')+' Постоянные расходы ещё не учтены.','hint'),button=create('button',state.selected===m.id?'Выбрано ✓':'Выбрать направление','secondary');button.type='button';button.onclick=()=>{if(state.selected!==m.id){state.selected=m.id;state.formatIndex=0;state.finance={};state.done={};state.milestonesDone={};}save();drawIdeas();};card.classList.toggle('picked',m.id===state.selected);const why=create('details',undefined,'wizard-disclosure');why.append(create('summary','Почему предложено это направление'));const whyList=create('ul');for(const reason of reasons)whyList.append(create('li',reason));why.append(whyList);const compareLabel=create('label','Сравнить'),compareBox=create('input');compareBox.type='checkbox';compareBox.checked=(state.compareIds||[]).includes(m.id);compareBox.onchange=()=>{let list=Array.isArray(state.compareIds)?state.compareIds:[];if(compareBox.checked&&!list.includes(m.id)){if(list.length>=3){compareBox.checked=false;$('wizardError').textContent='Можно сравнить не более трёх направлений';return;}list=[...list,m.id];}else if(!compareBox.checked){list=list.filter(id=>id!==m.id);}state.compareIds=list;$('wizardError').textContent='';save();drawIdeas();};compareLabel.prepend(compareBox);card.append(h,meta,tag,detail,why,compareLabel,button);root.append(card);}compareIdeas(root);}
function marketEvidence(){const evidence=window.GPRO_MARKET_EVIDENCE;if(!evidence)return null;const m=selected(),item=evidence.marketModels[m?.id]||{},sources=evidence.sources.filter(x=>(item.sourceIds||[]).includes(x.id));return{sources,note:item.note||'',checklist:evidence.checklist,official:evidence.sources.filter(x=>x.type==='official')};}
function appendMarketEvidence(root){const data=marketEvidence();if(!data)return;const d=create('details',undefined,'wizard-disclosure');d.append(create('summary','Универсальная методика: цена, затраты, спрос и источники'));d.append(create('p','Начальные цифры — сценарные ориентиры для моделирования, а не средние цены по городу. Важнее понять из чего состоит прибыль, проверить жизнеспособность и только затем уточнить реальные предложения.','hint'));for(const row of window.GPRO_MARKET_EVIDENCE.universalGuide||[]){const line=create('p');line.append(create('strong',row.title+': '),document.createTextNode(row.detail));d.append(line);}const list=create('ol');for(const step of data.checklist){list.append(create('li',step));}d.append(list);d.append(create('p','Правовые и налоговые справочные материалы:','hint'));for(const source of data.official){const item=create('p');const link=create('a',source.title);link.href=source.url;link.target='_blank';link.rel='noopener noreferrer';item.append(link);d.append(item);}root.append(d);}
function details(){const m=selected(),root=$('chosenIdea');root.replaceChildren();if(!m)return;root.append(create('h3',m.title));appendMarketEvidence(root);const op=operation(),b=brief();if(op){for(const [title,body]of [['Первый тест конкретно этой модели',op.validation],['Как выполнить первый заказ',op.delivery],['Как правильно считать расходы',op.costs]]){const d=create('details',undefined,'wizard-disclosure');d.open=title==='Первый тест конкретно этой модели';d.append(create('summary',title),create('p',body));root.append(d);}}if(b){root.append(create('p','Конкретная модель: '+b.product+'. Сейчас разберём её суть и подготовку; пошаговые действия будут на этапе 5, а сводный бизнес-план — на этапе 6.','wizard-intro'));for(const [heading,body]of [['Кому именно продаём',b.customers],['Что нужно подготовить',b.equipment],['Как формировать цену',b.pricing],['Первое практическое действие',b.firstTest]]){const block=create('details',undefined,'wizard-disclosure');block.open=heading==='Кому именно продаём'||heading==='Первое практическое действие';block.append(create('summary',heading),create('p',body));root.append(block);}}const expanded=expandedGuide();if(expanded){const d=create('details',undefined,'wizard-disclosure');d.open=true;d.append(create('summary',expanded.title),create('p',expanded.steps.map(x=>x[0]+': '+x[1]).join('\n\n')));root.append(d);}const cap=capitalGuide();if(cap){root.append(create('p',cap.red,'wizard-intro'));const d=create('details',undefined,'wizard-disclosure');d.open=true;d.append(create('summary',cap.title),create('p',cap.steps.map(x=>x[0]+': '+x[1]).join('\n\n')));root.append(d);}const special=specialist();if(special){const d=create('details',undefined,'wizard-disclosure');d.open=true;d.append(create('summary',special.heading),create('p',special.steps.map(x=>x[0]+': '+x[1]).join('\n\n')));root.append(d);}const pb=playbook();if(pb){root.append(create('p','Сначала выбери, что именно ты будешь продавать. Цена частного праздника и продажа отдельных мест на финансовую игру — разные модели.','hint'));const label=create('label','Формат проведения'),select=create('select');pb.formats.forEach((f,i)=>{const option=create('option',f.name);option.value=i;select.append(option);});select.value=state.formatIndex||0;select.onchange=()=>{state.formatIndex=Number(select.value);state.finance={};save();details();};label.append(select);root.append(label);const f=chosenFormat();for(const [name,value]of [['Что получает покупатель',f.product],['Что подготовить',f.kit],['Как искать первых клиентов',pb.days.slice(2,5).map(x=>x[2]).join(' ')]] ){const d=create('details',undefined,'wizard-disclosure');d.open=name==='Что получает покупатель';d.append(create('summary',name),create('p',value));root.append(d);} }if(cleaning()){const c=cleaning();root.append(create('p',c.intro,'wizard-intro'));for(const pkg of c.packages){const d=create('details',undefined,'wizard-disclosure');d.append(create('summary',pkg.name),create('p',pkg.scope+' '+pkg.sample));root.append(d);}const d=create('details',undefined,'wizard-disclosure');d.open=true;d.append(create('summary','С чего начать: первые 10 дней'),create('p',c.days.slice(0,5).map(x=>x[0]+': '+x[2]).join('\n\n')));root.append(d);}const g=guide(),tp=modelPlan();if(tp&&!cleaning()){root.append(create('p','Твой первый практический шаг: '+(brief()?.firstTest||m.validation),'wizard-intro'));for(const [heading,body]of [['Как получить первый заказ',tp.stages.slice(2,5).map(x=>x[0]+': '+x[1]).join('\n\n')],['Пример объявления для доработки',tp.ad],['Как предложить сотрудничество',tp.partner],['Как выполнять заказ и контролировать результат',g?.first+' '+g?.safety],['Какие расходы проверить',m.costs+'. '+(g?.unit||'Один оплаченный заказ')+'. Не считай выручку прибылью.']]){const d=create('details',undefined,'wizard-disclosure');d.open=heading==='Как получить первый заказ';d.append(create('summary',heading),create('p',body));root.append(d);}}else{for(const [title,value]of [['Кому продаём',m.audience],['Конкретное предложение',m.offer],['Как искать клиентов',m.channels],['Основные затраты',m.costs],['Риски и ограничения',m.risks],['Тест без крупных вложений',m.validation]]){const d=create('details',undefined,'wizard-disclosure');d.append(create('summary',title),create('p',value));root.append(d);}}if(g){for(const [title,body]of [['Как устроена эта модель',g.role],['Что конкретно понадобится',g.kit],['Первые клиенты: где и как искать',g.channels],['Самый первый тест спроса',g.first],['Критичные риски и требования',g.safety]]){const d=create('details',undefined,'wizard-disclosure');d.append(create('summary',title),create('p',body));root.append(d);}}root.append(create('p','Суммы из базы — исходные гипотезы. Проверь цены, требования закона и спрос в своём городе до вложений.','hint'));}
function financeDefaults(){const m=selected();if(!m)return;const f=chosenFormat();state.finance={ticket:f?.ticket||m.ticket,variable:f?.variable??m.variable,acquisition:f?.acquisition??Math.round(m.ticket*.07),fixed:0,tax:0,taxChecked:false,hours:f?.hours||m.hours,utilization:40,units:1,role:(m.id==='deep-29'?'solo':((['rental','season'].includes(m.category)&&/аренд|прокат|доск|вендинг/i.test(m.title))||/сдача автомобиля в аренду|кофейный вендинговый автомат|почасовая аренда кабинета|субаренда коммерческого помещения|субаренда рабочего места/i.test(m.title))?'asset':'solo'),labor:0,workerHours:m.hours,workers:1,dailySales:20,openDays:26,stockUnits:5,startup:m.minCapital,workingCapital:0,reserve:0,monthlyPayroll:0,payrollBurden:0,staffHours:140,maintenance:0,otherMonthly:0,ownerHourly:0,seasonMonths:12,seasonStart:1,shiftHours:0,shiftStaff:0,...state.finance};}
function readFinance(){return Object.fromEntries(['ticket','variable','acquisition','fixed','tax','hours','utilization','units','labor','workerHours','workers','dailySales','openDays','stockUnits','startup','workingCapital','reserve','monthlyPayroll','payrollBurden','staffHours','maintenance','otherMonthly','ownerHourly','seasonMonths','seasonStart','shiftHours','shiftStaff'].map(id=>[id,$('f_'+id)?Number($('f_'+id).value):Number(state.finance[id])]));}
function calc(){const f=state.finance,p=state.inputs,m=selected(),role=f.role||'solo',num=(k,d=0)=>Number.isFinite(+f[k])?Math.max(0,+f[k]):d;const name=m?.title||'',intermediary=m?.id==='deep-29',monthlyLease=['deep-5','deep-new-9'].includes(m?.id),spaceRent=m?.id==='deep-6',vending=/вендинг|автомат/i.test(name),food=/точка кофе с собой|точка шаурмы/i.test(name),resale=m?.category==='resale',rental=role==='asset'&&!vending&&!food&&!intermediary&&!spaceRent&&!monthlyLease,kind=vending?'drink':food?'receipt':resale?'goods':rental?'rental':monthlyLease?'lease':spaceRent?'space':'service',unitLabel=kind==='drink'?'напитков':kind==='receipt'?'чеков':kind==='goods'?'товаров':kind==='rental'?'оплаченных суток':kind==='space'?'оплаченных слотов':kind==='lease'?'занятых мест':'заказов';const monthlyHours=Math.max(0,Number(p.hours)||0)*4.33,price=num('ticket'),variable=num('variable'),acquisition=num('acquisition'),tax=num('tax'),labor=role==='manager'?num('labor'):0;const margin=price-variable-acquisition-labor-price*tax/100,units=Math.max(1,Math.floor(num('units',1))),workers=Math.max(1,Math.floor(num('workers',1))),hours=Math.max(.01,num('hours',1)),rate=Math.min(1,num('utilization')/100),seasonRate=Math.min(1,num('seasonMonths',12)/12);const ownCapacity=Math.floor(monthlyHours/hours),staffHours=workers*num('staffHours',140),staffCap=role==='manager'?Math.floor(staffHours/Math.max(.5,num('workerHours',1))):Infinity;let physicalCap=Infinity,baseCapacity=ownCapacity;if(vending){physicalCap=units*num('dailySales')*num('openDays');baseCapacity=physicalCap;}else if(food){physicalCap=num('dailySales')*num('openDays');baseCapacity=physicalCap;}else if(rental){physicalCap=units*Math.min(31,num('openDays',30));baseCapacity=Math.min(physicalCap,ownCapacity);}else if(monthlyLease){physicalCap=units;baseCapacity=physicalCap;}else if(spaceRent){physicalCap=units*num('openDays',26);baseCapacity=physicalCap;}else if(resale){physicalCap=Math.floor(num('stockUnits'));baseCapacity=Math.min(physicalCap,ownCapacity);}else baseCapacity=Math.min(ownCapacity,staffCap);const staffMonthly=num('monthlyPayroll'),payrollBurden=staffMonthly*num('payrollBurden')/100,monthlyFixed=num('fixed')+staffMonthly+payrollBurden+num('maintenance')+num('otherMonthly'),hardCapacity=Math.max(0,Math.floor(baseCapacity)),capacity=Math.floor(hardCapacity*rate),revenue=capacity*price,contribution=capacity*margin,operatingProfit=contribution-monthlyFixed,annualOperatingProfit=operatingProfit*12*seasonRate-monthlyFixed*12*(1-seasonRate),avgMonthlyProfit=annualOperatingProfit/12,initial=num('startup',m?.minCapital||0),workingCapital=num('workingCapital'),reserve=num('reserve'),fundingNeed=initial+workingCapital+reserve,budget=Math.max(0,+p.budget||0),shortfall=Math.max(0,fundingNeed-budget),ownerMonthlyValue=monthlyHours*num('ownerHourly'),economicProfit=operatingProfit-ownerMonthlyValue,orders=margin>0?Math.ceil(((+p.target||0)+monthlyFixed)/margin):Infinity,breakEven=margin>0?Math.ceil(monthlyFixed/margin):Infinity,payback=avgMonthlyProfit>0?Math.ceil((initial+workingCapital)/avgMonthlyProfit):Infinity,possible=Number.isFinite(orders)&&orders<=capacity&&shortfall===0,alerts=[];if(!f.taxChecked)alerts.push('Налоговая ставка пока не подтверждена. Ноль процентов по умолчанию не означает освобождение от налогов.');if(shortfall>0)alerts.push('Не хватает стартового финансирования: '+money(shortfall)+'.');if(capacity<orders)alerts.push('При указанной загрузке финансовая цель не достигнута.');if((food||vending)&&monthlyFixed===0)alerts.push('Постоянные расходы равны нулю: проверь аренду, персонал и обслуживание.');if(food&&num('shiftHours')>0&&num('shiftStaff')>0&&staffHours<num('openDays')*num('shiftHours')*num('shiftStaff'))alerts.push('Указанных часов сотрудников не хватает на все смены.');if(food&&staffMonthly===0)alerts.push('Для точки общепита не указаны зарплаты: укажи ФОТ или проверь, кто фактически работает в сменах.');if(role==='manager'&&labor>0&&staffMonthly>0)alerts.push('Убедись, что зарплата за заказ и месячный ФОТ относятся к разным людям/выплатам, иначе затраты посчитаются дважды.');if(role==='manager'&&labor===0&&staffMonthly===0)alerts.push('Не указана оплата исполнителей.');if(seasonRate<1)alerts.push('Сезонный бизнес: вне активных месяцев доход уменьшен, регулярные расходы остаются.');return{margin,orders,capacity,hardCapacity,timeCapacity:ownCapacity,staffCap,physicalCap,possible,profit:operatingProfit,payback,initial,asset:rental,rate,units,role,kind,unitLabel,vending,food,resale,monthlyHours,revenue,contribution,monthlyFixed,staffMonthly,payrollBurden,operatingProfit,economicProfit,avgMonthlyProfit,annualOperatingProfit,breakEven,workingCapital,reserve,fundingNeed,shortfall,ownerMonthlyValue,alerts};}
function financeTimeline(){const r=calc(),f=state.finance,active=Math.max(1,Math.min(12,Math.round(Number(f.seasonMonths)||12))),start=Math.max(1,Math.min(12,Math.round(Number(f.seasonStart)||1)));let cash=(Number(state.inputs.budget)||0)-r.initial-r.workingCapital;const months=[];for(let month=1;month<=12;month++){const offset=(month-start+12)%12,isActive=offset<active,sales=isActive?r.capacity:0,inflow=sales*(Number(f.ticket)||0),cost=sales*((Number(f.variable)||0)+(Number(f.acquisition)||0)+(r.role==='manager'?(Number(f.labor)||0):0)+((Number(f.ticket)||0)*(Number(f.tax)||0)/100))+r.monthlyFixed,flow=inflow-cost;cash+=flow;months.push({month,active:isActive,sales,inflow,cost,flow,cash});}return{months,minCash:Math.min(...months.map(x=>x.cash)),cashAtStart:(Number(state.inputs.budget)||0)-r.initial-r.workingCapital,active,start};}
function scenarioView(){const host=$('scenarioResult');if(!host)return;host.replaceChildren();const wrap=create('details',undefined,'wizard-disclosure');wrap.append(create('summary','Три варианта экономики: осторожный, базовый и оптимистичный'));if(calc().margin<=0)wrap.append(create('p','⚠ Маржа с продажи неположительная: рост объёма ухудшит результат без изменения цены или затрат.','hint'));wrap.append(create('p','Это тест изменения цены, спроса и прямых расходов при одинаковых постоянных расходах. Ни один сценарий не подтверждает наличие покупателей. Объём ограничен расчётной мощностью модели.','hint'));for(const x of universalScenarios()){const line=create('div',undefined,'calc-line');line.append(create('span',x.name+': '+x.units+' '+x.unitLabel+'; цена '+money(x.price)),create('strong',money(x.profit)+' / мес.'));wrap.append(line);}host.append(wrap);}
function financeTimelineView(){const host=$('timelineResult');if(!host)return;const t=financeTimeline();host.replaceChildren();const d=create('details',undefined,'wizard-disclosure');d.append(create('summary','Денежный поток: условные 12 месяцев'));d.append(create('p','Активный сезон начинается с месяца №'+t.start+' и длится '+t.active+' мес. Месяцы — условный календарный год, сезон может переходить через декабрь. На старте из доступного бюджета вычтены вложения и оборотный капитал; резерв остаётся деньгами, а не расходом. Дефицит финансирования проверь отдельно.','hint'));for(const x of t.months){const line=create('div',undefined,'calc-line');line.append(create('span','Месяц '+x.month+(x.active?' · активный':' · вне сезона')+' · '+x.sales+' продаж'),create('strong','Поток '+money(x.flow)+' · остаток '+money(x.cash)));d.append(line);}if(t.minCash<0)d.append(create('p','⚠ Модельный денежный остаток становится отрицательным. Нужны дополнительное финансирование, меньшие расходы или корректировка плана.','hint'));host.append(d);}
function universalScenarios(){const r=calc(),f=state.finance,baseMax=r.rate>0?Math.ceil(r.capacity/r.rate):r.capacity;const hardCap=Math.max(0,Number.isFinite(baseMax)?baseMax:r.capacity);return [['Осторожный',.5,.9,1.1],['Базовый',1,1,1],['Оптимистичный',1.35,1.05,1]].map(([name,volume,priceFactor,costFactor])=>{const units=Math.min(hardCap,Math.max(0,Math.floor(r.capacity*volume))),price=(Number(f.ticket)||0)*priceFactor,variable=(Number(f.variable)||0)*costFactor,acquisition=Number(f.acquisition)||0,labor=r.role==='manager'?Number(f.labor)||0:0,tax=price*(Number(f.tax)||0)/100,margin=price-variable-acquisition-labor-tax,profit=units*margin-r.monthlyFixed,breakEven=margin>0?Math.ceil(r.monthlyFixed/margin):Infinity;return{name,units,price,margin,profit,revenue:units*price,breakEven,volume,priceFactor,costFactor,feasible:units>=breakEven,unitLabel:r.unitLabel};});}
function metrics(){const r=calc(),root=$('financeResult');root.replaceChildren();for(const [label,value]of [['Вклад с одной продажи',money(r.margin)],['Продаж для цели',Number.isFinite(r.orders)?String(r.orders):'Недостижимо'],['Модельная загрузка',String(r.capacity)+' '+r.unitLabel+'/мес.'],['Операционный результат / месяц',money(r.profit)],['Среднее за год с учётом сезона',money(r.avgMonthlyProfit)],['Точка безубыточности',Number.isFinite(r.breakEven)?r.breakEven+' '+r.unitLabel:'Не достигается'],['Всего необходимо на запуск',money(r.fundingNeed)],['Нехватка бюджета',money(r.shortfall)],['Ориентировочная окупаемость вложений и оборотного капитала',Number.isFinite(r.payback)?'около '+r.payback+' мес. при заданной загрузке':'Не рассчитан']]){const b=create('div',undefined,'wizard-stat');b.append(create('span',label),create('strong',value));root.append(b);}root.append(create('p','Тип операции: '+r.unitLabel+'. '+(['drink','receipt'].includes(r.kind)?'Продажи ограничены указанными продажами в день и рабочими днями; часы владельца следует отдельно проверять на достаточность для организации работы. ':r.kind==='goods'?'Продажи ограничены доступным товарным запасом и временем предпринимателя. ':'Расчётная мощность по времени: '+r.timeCapacity+' операций/мес. ')+'Используется '+Math.round(r.rate*100)+'% предполагаемой загрузки. '+(r.asset?'Для актива это лишь верхняя оценка: дни аренды, покупатели, доступность оборудования и спрос нужно проверять отдельно. ':'')+'Начальные вложения не уменьшают месячную прибыль, но должны возвращаться из неё.','hint'));if(['drink','receipt'].includes(r.kind)&&state.finance.fixed===0)root.append(create('p','Внимание: постоянные расходы равны нулю. Для точки или автомата это обычно нереалистично; укажи аренду, сервис, коммунальные и оплату персонала до принятия решения.','hint'));for(const issue of r.alerts)root.append(create('p','⚠ '+issue,'hint'));root.append(create('p',r.possible?'По этим допущениям цель укладывается в график. Реальные продажи ещё нужно подтвердить.':'При данных условиях цель не укладывается в доступные часы или в экономику. Измени цену, расходы либо выбери другую модель.','hint'));}
function explainFinance(){const r=calc(),f=state.finance,host=$('financeExplain');if(!host)return;host.replaceChildren();const d=create('details',undefined,'wizard-disclosure');d.open=true;d.append(create('summary','Откуда получилась прибыль: подробный расчёт'));const items=[['Выручка с заказа',money(f.ticket)],['Материалы, транспорт и другие затраты', '− '+money(f.variable)],['Привлечение одного оплаченного заказа','− '+money(f.acquisition)],['Оплата исполнителя',r.role==='manager'?'− '+money(f.labor):'Не применяется'],['Налоговый сценарий '+f.tax+'%', '− '+money(f.ticket*f.tax/100)],['Остаётся с одного заказа',money(r.margin)],['Предполагаемые продажи в месяц',String(r.capacity)+' '+r.unitLabel],['Вклад всех заказов',money(r.capacity*r.margin)],['Постоянные и регулярные расходы месяца','− '+money(r.monthlyFixed)],['В том числе фонд оплаты труда',money(r.staffMonthly)],['В том числе начисления на ФОТ',money(r.payrollBurden)],['Операционный результат месяца',money(r.profit)],['Среднее в месяц с учётом сезона',money(r.avgMonthlyProfit)],['Стоимость времени владельца (для сравнения)','− '+money(r.ownerMonthlyValue)],['Экономический результат с оценкой своего времени',money(r.economicProfit)],['Потребность в деньгах при запуске',money(r.fundingNeed)]];for(const [k,v]of items){const line=create('div',undefined,'calc-line');line.append(create('span',k),create('strong',v));d.append(line);}d.append(create('p','Прогноз строится по введённым допущениям о спросе и загрузке. Это не подтверждённые продажи, а расчётный сценарий. Стоимость привлечения пока можно оценить только условно; после теста замените цифру на реальные затраты на рекламу / количество оплаченных заказов.','hint'));host.append(d);}
function drawFinance(){financeDefaults();const root=$('economics');root.replaceChildren();const m=selected();appendMarketEvidence(root);root.append(create('h3','Проверяем '+(chosenFormat()?.name||m.title)));if(/вендинг|автомат/i.test(m.title))root.append(create('p','Для вендинга одна операция — проданный напиток, а часы предпринимателя — пополнение, обслуживание и контроль. Текущий расчёт количества операций ограничен введёнными личными часами и является грубым приближением: продажи в день и загрузку локации необходимо отдельно проверять.','wizard-intro'));if(/сдача автомобиля в аренду/i.test(m.title))root.append(create('p','При аренде автомобиля одна операция — оплаченные сутки. Включи в затраты страховку, обслуживание, ремонт, транспорт, мойку и простой; не приравнивай суточную выручку к прибыли.','wizard-intro'));const modelType=calc().kind;root.append(create('p',modelType==='drink'?'Здесь одна продажа — чашка напитка. Укажи ожидаемые чашки за рабочий день и количество дней. Загрузка — доля от этой мощности; время владельца указывается отдельно и НЕ ограничивает число проданных напитков.':modelType==='receipt'?'Здесь одна продажа — чек посетителя. Обязательно включи в постоянные расходы аренду, оплату смен и другие регулярные платежи, а в прямые — ингредиенты и упаковку.':modelType==='goods'?'Здесь одна продажа — единица товара. Укажи сколько единиц реально можешь закупать и продавать в месяц: закупочную цену включай в прямые затраты на единицу. Деньги в остатках товара — не прибыль.':modelType==='lease'?'Одна продажа — занятое место или помещение за месяц. Введи количество мест и среднюю месячную выручку с одного занятого места. Простои учитывай загрузкой.':modelType==='space'?'Одна продажа — оплаченный слот пространства. Определи, сколько слотов доступно за рабочий день; постоянную аренду, коммунальные и простой внеси отдельно.':modelType==='rental'?'Одна продажа — оплаченные сутки одной единицы оборудования. Внеси количество вещей, рабочие дни и долю фактической загрузки.':'Расчёт по выполненным заказам и времени предпринимателя.','wizard-intro'));root.append(create('p','Цифры ниже — стартовые ориентиры для выбранного формата, а не рыночная статистика. Если ты ещё не знаешь стоимость рекламы, оставь предварительное значение и проверь его после первых заказов: расходы на рекламу ÷ число оплаченных заказов. Не включай рекламу второй раз в прямые затраты.','hint'));const roleLabel=create('label','Твоя роль в бизнесе'),roleInput=create('select');for(const [v,n]of [['solo','Сам выполняю заказ'],['manager','Организую работу исполнителей'],['asset','Владею активом и сдаю его']]){const o=create('option',n);o.value=v;roleInput.append(o);}roleInput.value=state.finance.role;roleInput.onchange=()=>{state.finance.role=roleInput.value;save();drawFinance();};roleLabel.append(roleInput);root.append(roleLabel);root.append(create('p',state.finance.role==='manager'?'Твои часы — заявки и управление; выполнение учитывается отдельно.':state.finance.role==='asset'?'Твои часы — бронирование, выдача, возврат и обслуживание.':'Твои часы — выполнение, дорога, подготовка и переговоры.','hint'));const grid=create('div',undefined,'wizard-fin-grid');for(const [id,label,min,max,step]of [['ticket','Средний чек, ₽',100,1e8,100],['variable','Прямые затраты на заказ, ₽',0,1e8,100],['acquisition','Привлечение одного заказа, ₽',0,1e8,100],['fixed','Постоянные расходы в месяц, ₽',0,1e9,100],['tax','Налоговый сценарий, %',0,50,1],['hours','Твоих часов на одну продажу / выдачу',.5,1000,.5],['utilization','Ожидаемая загрузка возможностей, %',0,100,5],['units','Единиц оборудования',1,100,1],['labor','Оплата исполнителя за заказ, ₽',0,1e8,100],['workerHours','Часы исполнителя на заказ',.5,1000,.5],['workers','Число исполнителей',1,100,1],['dailySales','Продаж в день при полной загрузке',0,10000,1],['openDays','Рабочих дней в месяц',0,31,1],['stockUnits','Доступных товаров для продажи в месяц',0,100000,1],['startup','Первоначальные вложения, ₽',0,1e9,1000],['workingCapital','Оборотный капитал на закупки, ₽',0,1e9,1000],['reserve','Резерв денег на непредвиденное, ₽',0,1e9,1000],['monthlyPayroll','Фонд зарплат за месяц, ₽',0,1e9,1000],['payrollBurden','Начисления на ФОТ, % (введи свой сценарий)',0,100,1],['staffHours','Часов на одного сотрудника в месяц',1,300,1],['maintenance','Обслуживание и ремонт в месяц, ₽',0,1e9,100],['otherMonthly','Другие регулярные расходы в месяц, ₽',0,1e9,100],['ownerHourly','Оценка стоимости часа владельца, ₽',0,100000,100],['seasonMonths','Активных месяцев в году',1,12,1],['seasonStart','Первый активный месяц (1 = январь)',1,12,1],['shiftHours','Часов работы точки в день',0,24,1],['shiftStaff','Сотрудников одновременно в смене',0,30,1]]){if(state.finance.role!=='manager'&&['labor','workerHours','workers'].includes(id))continue;const k=calc().kind;if(['dailySales','openDays'].includes(id)&&!['drink','receipt','rental','space'].includes(k))continue;if(id==='dailySales'&&['rental','space'].includes(k))continue;if(id==='stockUnits'&&k!=='goods')continue;if(['shiftHours','shiftStaff'].includes(id)&&k!=='receipt')continue;if(state.finance.role!=='asset'&&id==='units')continue;const l=create('label',label),input=create('input');input.id='f_'+id;input.type='number';input.min=min;input.max=max;input.step=step;input.value=state.finance[id];input.oninput=()=>{let v=Number(input.value);if(input.value===''||!Number.isFinite(v)||v<min||v>max){$('wizardError').textContent='Проверь значения в экономике';return;}state.finance={...state.finance,...readFinance()};$('wizardError').textContent='';metrics();explainFinance();scenarioView();financeTimelineView();save();};l.append(input);grid.append(l);}root.append(grid);if(state.finance.role==='manager'&&state.finance.labor<=0)root.append(create('p','Не забудь оплату исполнителю. Без неё расчёт завышает прибыль.','hint'));root.append(create('p','Средний чек — выручка за один заказ, не чистая прибыль. Прямые расходы: только материалы, транспорт, расходники и оплата исполнителя, если она есть. Реклама — отдельно. Примерная стоимость клиента = расходы на продвижение / оплаченные заказы; при нуле заказов её пока не определить. Для аренды считай также износ, ремонт, простой и сезон.','hint'));root.append(create('p','Важно: НПД нельзя применять при перепродаже закупленных товаров или наличии работников по трудовому договору. Для торговой точки, вендинга и работы с сотрудниками проверь подходящий налоговый режим и требования к кассе.','hint'));root.append(create('p','Поле «ФОТ» — зарплаты за месяц. Не дублируй в нём оплату тех же исполнителей, если она уже записана в затратах на заказ. Начальный оборотный капитал — деньги на закупки, а не дополнительный расход на каждую продажу: закупочная себестоимость уже учитывается в прямых затратах. Резерв — запас денег, не бухгалтерский убыток.','hint'));const taxCheck=create('label');const taxBox=create('input');taxBox.type='checkbox';taxBox.checked=!!state.finance.taxChecked;taxBox.onchange=()=>{state.finance.taxChecked=taxBox.checked;metrics();explainFinance();scenarioView();financeTimelineView();save();};taxCheck.append(taxBox,document.createTextNode(' Я проверил налоговый режим и самостоятельно ввёл применимую ставку сценария'));root.append(taxCheck);root.append(create('p','Налог здесь — параметр сценария, не автоматический выбор режима. Учти требования ФНС, возвраты и простои.','hint'));const result=create('div',undefined,'wizard-stats');result.id='financeResult';root.append(result);const explanation=create('div');explanation.id='financeExplain';root.append(explanation);const scenarioEl=create('div');scenarioEl.id='scenarioResult';root.append(scenarioEl);const timelineEl=create('div');timelineEl.id='timelineResult';root.append(timelineEl);metrics();explainFinance();scenarioView();financeTimelineView();}
